
.palace {
  padding: 10px;
  border-top: 1px solid var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.head {
  font-size: 12px;
  font-weight: normal;
  letter-spacing: 2px;
  color: var(--c-secondary);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 4px;
}

.row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
}

.row-label {
  color: var(--c-text-muted);
  letter-spacing: 1px;
}

.row-note {
  font-size: 10px;
  color: var(--c-text-muted);
  white-space: nowrap;
}

.empress {
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  padding: 7px 9px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.empress-name {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.label {
  font-size: 10px;
  color: var(--c-text-muted);
  letter-spacing: 1px;
}

.value {
  font-family: var(--font-accent);
  font-size: 14px;
  letter-spacing: 3px;
  color: var(--c-primary);
}

.public,
.truth {
  font-size: 11px;
  line-height: 1.5;
  color: var(--c-text-muted);
}

.truth {
  color: var(--c-seal);
}

.gift {
  font-family: var(--font-accent);
  letter-spacing: 2px;
}

.ladder {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  list-style: none;
}

.ladder li {
  text-align: center;
  font-size: 10.5px;
  padding: 2px 0;
  color: var(--c-text-muted);
  border-top: 2px solid var(--c-border);
  transition: all 260ms var(--ease-gentle);
}

.ladder li.is-done {
  color: var(--c-secondary);
  border-top-color: var(--c-secondary);
}

.ladder li.is-now {
  font-weight: bold;
}
