
.scroll {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  box-shadow: 0 1px 0 rgba(43, 33, 24, 0.06);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.unfold-enter-active,
.unfold-leave-active {
  transition:
    opacity 260ms var(--ease-gentle),
    transform 260ms var(--ease-gentle);
}

.unfold-enter-from,
.unfold-leave-to {
  opacity: 0;
  transform: translateY(-4px);
}
