
.annex {
  padding: 10px;
  border-top: 1px solid var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.head {
  font-size: 12px;
  font-weight: normal;
  letter-spacing: 2px;
  color: var(--c-primary);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 4px;
}

.count {
  float: right;
  font-size: 10px;
  color: var(--c-text-muted);
  letter-spacing: 0;
}

.none {
  font-size: 11px;
  color: var(--c-text-muted);
}

.group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.group-head {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--c-secondary);
  letter-spacing: 1px;
}

.layer-count {
  font-size: 10px;
  color: var(--c-text-muted);
}

.list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.list li {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
  font-size: 11.5px;
  padding: 4px 7px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
}

.name {
  font-family: var(--font-accent);
  letter-spacing: 2px;
  color: var(--c-primary);
}

.identity {
  color: var(--c-text-muted);
  font-size: 10.5px;
}

.token {
  margin-left: auto;
  font-size: 10px;
  color: var(--c-text-muted);
}

.token.has-token {
  color: var(--c-seal);
}

.state {
  font-size: 10px;
  padding: 0 5px;
  border: 1px solid var(--c-border);
}

.state-情人 {
  color: var(--c-accent);
  border-color: var(--c-accent);
}

.state-了结 {
  color: var(--c-text-muted);
}

.echo {
  font-size: 11px;
  color: var(--c-danger);
  border-left: 2px solid var(--c-danger);
  padding-left: 7px;
  line-height: 1.5;
}
