
.card {
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.card-head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
}

.name {
  font-family: var(--font-accent);
  font-size: 17px;
  letter-spacing: 3px;
  color: var(--c-primary);
}

.age {
  font-size: 11px;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
}

.identity {
  font-size: 11px;
  color: var(--c-text);
  padding: 1px 6px;
  border: 1px solid var(--c-border);
  background: var(--c-surface-raised);
}

.row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
}

.row-label {
  flex: 0 0 auto;
  color: var(--c-text-muted);
  letter-spacing: 1px;
}

.row-text {
  color: var(--c-text);
}

.token-hint {
  margin-left: auto;
  color: var(--c-seal);
  font-size: 10px;
}

.ladder {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 3px;
  list-style: none;
}

.ladder li {
  text-align: center;
  font-size: 10px;
  padding: 2px 0;
  color: var(--c-text-muted);
  border-top: 2px solid var(--c-border);
  transition: all 260ms var(--ease-gentle);
}

.ladder li.is-done {
  color: var(--c-primary);
  border-top-color: var(--c-primary-soft);
}

.ladder li.is-now {
  color: var(--c-accent);
  border-top-color: var(--c-accent);
  font-weight: bold;
}

.detail {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 6px;
}

.detail > div {
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  padding: 5px 7px;
}

.detail .wide {
  grid-column: 1 / -1;
}

.detail dt {
  font-size: 10px;
  color: var(--c-text-muted);
  letter-spacing: 1px;
}

.detail dd {
  font-size: 12px;
  line-height: 1.45;
}
